                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            mr = min(y for y, x in cells)
            mc = min(x for y, x in cells)
            shp = frozenset((y - mr, x - mc) for y, x in cells)
            comps.append((color, cells, shp))

    out = [row[:] for row in grid]
    five_shapes = [s for color, cells, s in comps if color == 5]
    recolor = []
    for color, cells, shp in comps:
        if color != 5 and shp in five_shapes:
            recolor.extend(cells)

