        by_shape = defaultdict(list)
        for color, cells, shp in comps:
            by_shape[shp].append((color, cells))
        for entries in by_shape.values():
            if len(entries) > 1 and any(color == 1 for color, _ in entries):
                recolor.extend(cells for color, cells in entries if color == 1)
                break

    for cells in recolor:
        for r, c in cells:
